args.script:
(() => {
  const h = document.querySelector('#browser_compatibility');
  if (!h) return {error:'No browser_compatibility heading'};
  const section = h.closest('section') || h.parentElement;
  const text = section.innerText;
  const tables = [...section.querySelectorAll('table')].map(t => t.innerText);
  const bcd = document.querySelector('mdn-compat-table')?.getAttribute('data') || null;
  return {url: location.href, title: document.title, sectionText: text.slice(0, 5000), tableCount: tables.length, tables: tables.map(x => x.slice(0,3000)), compatTableOuter: document.querySelector('mdn-compat-table')?.outerHTML.slice(0,2000) || null};
})()

(() => {
  const main = document.querySelector('main') || document.body;
  const text = main.innerText || document.body.innerText;
  const headings = [...document.querySelectorAll('h1,h2,h3')].map(h => ({id:h.id, text:h.innerText}));
  const compatEls = [...document.querySelectorAll('*')].filter(el => (el.tagName || '').toLowerCase().includes('compat') || (el.className && String(el.className).includes('compat'))).slice(0,20).map(el => ({tag:el.tagName, id:el.id, cls:String(el.className), text:(el.innerText||'').slice(0,500), attrs:[...el.attributes].map(a=>[a.name,a.value])}));
  const scripts = [...document.scripts].map(s => ({src:s.src, txt:s.textContent.slice(0,200)})).filter(x => x.src.includes('compat') || x.txt.includes('grid-template-columns') || x.txt.includes('browser_compatibility')).slice(0,10);
  return {textStart:text.slice(0,2000), headings, compatEls, scripts};
})()

(() => {
  const text = (document.querySelector('main') || document.body).innerText;
  const idx = text.indexOf('Browser compatibility');
  const around = idx >= 0 ? text.slice(idx, idx + 5000) : text.slice(-5000);
  const tables = [...document.querySelectorAll('table')].map((t, i) => ({i, text: t.innerText.slice(0, 3000)}));
  const compat = [...document.querySelectorAll('[class*=compat], mdn-compat-table, browser-compatibility-table')].map((el, i) => ({
    i, tag: el.tagName, cls: String(el.className), text: (el.innerText || el.textContent || '').slice(0, 3000), html: el.outerHTML.slice(0, 1000)
  }));
  return {idx, around, tables, compatCount: compat.length, compat: compat.slice(0, 20)};
})()
